package com.mamtrex.hospital.surgery;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/surgeries") public class SurgicalCaseController { private final SurgicalCaseRepository repo; private final AuditService audit; public SurgicalCaseController(SurgicalCaseRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String patientId, @jakarta.validation.constraints.NotBlank String procedureName, @jakarta.validation.constraints.NotBlank String surgeonId, @jakarta.validation.constraints.NotBlank String scheduledAt, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public SurgicalCase create(@Valid @RequestBody Request r){var e=repo.save(new SurgicalCase(r.patientId(), r.procedureName(), r.surgeonId(), r.scheduledAt(), r.status()));audit.record("CREATE","SurgicalCase",e.getId().toString(),"created");return e;} @GetMapping public List<SurgicalCase> list(){return repo.findAll();} @GetMapping("/{id}") public SurgicalCase get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("SurgicalCase not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("SurgicalCase not found: "+id);repo.deleteById(id);audit.record("DELETE","SurgicalCase",id.toString(),"deleted");} }
